pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address callee, bytes memory _data) public {
        // Deploy a helper that always succeeds on call to ensure the external call itself does not revert
        SuccessCallee helper = new SuccessCallee();
        address helperAddr = address(helper);

        vm.prank(address(1));
        vm.deal(address(1), 0 ether);
        bool ok;
        try c.forward(helperAddr, _data) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}

contract SuccessCallee {
    fallback() external payable { }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address callee, bytes memory data) public {
        vm.assume(callee != address(c));
        // Deploy a helper that reverts on any call, including with data
        Reverter reverter = new Reverter();
        // Use the adversarial callee that always reverts
        bool ok;
        try c.forward(address(reverter), data) {
            ok = true;
        } catch {
            ok = false;
        }
        // The call must have reverted because reverter always reverts
        assertTrue(!ok);
    }
}
contract Reverter {
    fallback() external payable { revert(); }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(bytes memory _data) public {
        // Deploy a helper callee that always succeeds (empty fallback)
        Succeeder succ = new Succeeder();

        // Forward call should not revert when callee succeeds
        bool ok;
        try c.forward(address(succ), _data) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}

contract Succeeder {
    fallback() external payable {}
}
